.right-rail{border-left:1px solid var(--line);background:#fafbf7;padding:32px 19px 18px;display:flex;flex-direction:column}.rail-title{display:flex;justify-content:space-between;align-items:center;font:500 9px 'DM Mono',monospace;letter-spacing:1px;color:#929f96}.note-dot{height:5px;width:5px;border-radius:50%;background:#a9c98b}.daily-card{margin-top:16px;border:1px solid #e8eee1;background:#f1f5e9;border-radius:10px;padding:13px 12px}.daily-top{display:flex;align-items:center;gap:7px}.daily-icon{width:24px;height:24px;border-radius:7px;background:#fff9e9;display:grid;place-items:center;color:#e3b557;font-size:15px}.daily-top .eyebrow{font-size:8px}.daily-card h3{font:600 13px 'Space Grotesk',sans-serif;margin:12px 0 11px}.goal-progress{display:flex;align-items:center;gap:8px}.goal-bar{height:5px;background:#dfe8d8;border-radius:5px;flex:1;overflow:hidden}.goal-progress>span{font:8px 'DM Mono',monospace;color:#8f9b8e}.goal-reward{font:8px 'DM Mono',monospace;color:#98a48c;margin-top:10px}.goal-reward:first-letter{color:#dda949}.goal-reward b{color:#bb9456}.rail-divider{height:1px;background:var(--line);margin:21px 0 17px}.activity-heading{padding:0 2px}.log-live{display:flex;align-items:center;gap:5px;font:7px 'DM Mono',monospace;color:#9da99f}.log-live i{display:block;width:5px;height:5px;background:#8bc282;border-radius:50%}.activity-list{display:flex;flex-direction:column;gap:14px;margin:17px 1px 18px;min-height:145px}.activity-item{display:flex;align-items:flex-start;gap:9px;animation:fadein .3s ease}.activity-avatar{width:25px;height:25px;border-radius:8px;display:grid;place-items:center;font-size:13px;flex:none}.activity-text{font-size:9px;line-height:1.45;color:#75847a}.activity-text b{color:#445a4b;font-weight:700}.activity-time{display:block;color:#aab3ac;font:7px 'DM Mono',monospace;margin-top:3px}.empty-log{font-size:9px;line-height:1.5;color:#a1aba4}.tip-card{margin-top:auto;border-radius:9px;background:#f2f4ed;padding:11px 9px;display:flex;gap:8px;align-items:flex-start;position:relative}.tip-icon{font-size:17px;color:#93ac76}.tip-card .eyebrow{font-size:8px}.tip-card p{font-size:9px;line-height:1.45;color:#829086;margin:5px 0 0;padding-right:6px}.tip-card button{border:0;background:#e6ecdf;color:#8da282;border-radius:5px;width:20px;height:20px;padding:0;flex:none;font-size:11px}.rail-footer{display:flex;justify-content:space-between;margin-top:16px;font:7px 'DM Mono',monospace;color:#b1bbb2;letter-spacing:.6px}.hidden{display:none!important}.subpage-heading{margin-bottom:24px}.guide-total{background:#edf4e8;border-radius:9px;padding:8px 13px;text-align:center}.guide-total b{display:block;color:#4f8e5e;font:700 19px 'Space Grotesk',sans-serif}.guide-total span{font:7px 'DM Mono',monospace;color:#91a38f;letter-spacing:.7px}.guide-grid{display:grid;grid-template-columns:repeat(3,minmax(120px,1fr));gap:12px}.guide-card{border:1px solid #e7ece4;background:#fff;border-radius:11px;overflow:hidden;min-height:178px}.guide-art{height:113px;display:grid;place-items:center;position:relative;background:linear-gradient(180deg,#d9eee1,#edf2d7)}.guide-art .creature-mini{width:87px;height:87px;filter:drop-shadow(0 5px 3px #365b3150);animation:bob 3s infinite}.guide-art .creature-mini svg{width:100%;height:100%}.unknown-art{font-size:33px;color:#c3d0c0}.guide-card-copy{padding:9px 10px}.guide-card-copy b{font:600 11px 'Space Grotesk',sans-serif;display:block}.guide-card-copy span{font:8px 'DM Mono',monospace;color:#a0aaa2;display:block;margin-top:4px}.guide-card.undiscovered{opacity:.62}.camp-card{border:1px solid #e6ece2;background:#f0f5e9;border-radius:12px;min-height:175px;padding:20px;display:flex;align-items:center;gap:20px}.camp-illustration{height:114px;width:125px;border-radius:12px;background:linear-gradient(#cce4de,#e3efcc);display:grid;place-items:center;font-size:58px;position:relative;flex:none}.camp-illustration span{position:absolute;font-size:16px;right:24px;top:17px;color:#fff4c0}.camp-info .eyebrow{color:#729c71}.camp-info h2{font:600 18px 'Space Grotesk',sans-serif;margin:7px 0}.camp-info p{max-width:380px;color:#849287;font-size:10px;line-height:1.55;margin:0}.upgrade-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:17px}.upgrade-card{background:white;border:1px solid #e8ece5;border-radius:10px;padding:14px;display:flex;align-items:center;gap:10px}.upgrade-icon{height:36px;width:36px;border-radius:10px;background:#f7f1df;display:grid;place-items:center;font-size:19px}.upgrade-info{flex:1}.upgrade-info b{font-size:11px;display:block}.upgrade-info small{color:#9ba79d;font-size:8px;display:block;margin-top:3px;line-height:1.4}.upgrade-level{font:8px 'DM Mono',monospace;color:#86a280;margin-top:4px}.upgrade-buy{border:0;background:#edf5e8;color:#53815a;border-radius:6px;padding:7px 9px;font:600 9px 'DM Mono',monospace;white-space:nowrap}.upgrade-buy:disabled{opacity:.45;cursor:not-allowed}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#294b39;color:white;padding:10px 16px;border-radius:9px;font-size:11px;box-shadow:0 6px 20px #163a272b;transition:.25s;z-index:20;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:30;background:#19352872;display:grid;place-items:center;padding:18px}.modal-card{position:relative;width:min(420px,100%);background:#fff;border-radius:17px;padding:30px;text-align:center;box-shadow:0 20px 70px #11291b4d}.modal-close{position:absolute;right:14px;top:12px;border:0;background:#f2f5ef;color:#728276;border-radius:50%;height:27px;width:27px;font-size:18px}.modal-emblem{height:47px;width:47px;border-radius:15px;background:#eaf3e4;color:#69a466;display:grid;place-items:center;font-size:27px;margin:0 auto 15px}.modal-card .eyebrow{justify-content:center}.modal-card h2{font:700 22px 'Space Grotesk',sans-serif;letter-spacing:-.6px;margin:10px 0}.modal-card p{font-size:12px;line-height:1.65;color:#87938b;margin:0 0 20px}.modal-actions{display:flex;justify-content:center;gap:8px}.primary-small,.secondary-small{border:0;border-radius:7px;padding:10px 14px;font-size:10px;font-weight:700}.primary-small{background:#4f9463;color:white}.secondary-small{background:#f0f3ed;color:#758277}.modal-card>small{display:block;color:#a6afa7;font-size:9px;margin-top:17px}.mobile-nav{display:none}@keyframes fadein{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:1100px){.content-grid{grid-template-columns:205px minmax(430px,1fr) 235px}.sidebar{padding-left:13px;padding-right:13px}.right-rail{padding-left:14px;padding-right:14px}.main-area{padding-left:27px;padding-right:27px}.scene-art{height:300px}.battle-panel{gap:12px}.battle-feedback{padding-left:12px}.guide-grid{grid-template-columns:repeat(2,minmax(120px,1fr))}}
@media(max-width:840px){.content-grid{grid-template-columns:190px minmax(0,1fr)}.right-rail{display:none}.main-area{padding:25px 28px}.topbar{padding:0 24px}.scene-art{height:310px}.guide-grid{grid-template-columns:repeat(3,minmax(100px,1fr))}}
@media(max-width:620px){.topbar{height:60px;padding:0 15px}.brand{font-size:19px}.brand-mark{width:30px;height:30px}.header-center{font-size:8px;gap:7px}.header-actions{gap:6px}.coin-pill{height:30px;padding:0 9px;font-size:11px}.icon-button{width:30px;height:30px}.help-button{display:none}.content-grid{display:block;min-height:calc(100vh - 60px)}.sidebar{display:none}.main-area{padding:22px 15px 86px}.trail-heading,.subpage-heading{margin-bottom:17px}.trail-heading h1,.subpage-heading h1{font-size:27px}.subheading{font-size:10px}.zone-button{padding:0 8px}.scene-art{height:290px}.scene-topline{padding:0 12px}.battle-panel{grid-template-columns:1fr;gap:6px;height:72px;padding:10px 13px}.battle-feedback{border:0;padding:0;font-size:9px}.action-row{padding:0 10px 11px;gap:7px}.action-button{padding:0 8px;gap:6px;height:49px}.action-button b{font-size:10px}.action-button small{font-size:7px}.button-symbol{height:25px;width:25px;font-size:15px}.button-key{display:none}.trail-footer{padding-top:13px}.progress-track{display:none}.auto-button{min-width:107px;padding:0 7px}.mobile-nav{display:flex;position:fixed;z-index:15;bottom:0;left:0;right:0;height:62px;padding:5px 16px calc(5px + env(safe-area-inset-bottom));background:#fcfcf8;border-top:1px solid #e7ebe3;justify-content:space-around}.mobile-nav-item{border:0;background:transparent;color:#9ba79d;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:65px;font-size:9px}.mobile-nav-item span{font-size:19px;line-height:20px}.mobile-nav-item.active{color:#4f9060}.guide-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.guide-card{min-height:158px}.guide-art{height:100px}.guide-art .creature-mini{width:76px;height:76px}.camp-card{padding:13px;gap:13px;min-height:145px}.camp-illustration{width:90px;height:100px;font-size:45px}.camp-info h2{font-size:15px}.camp-info p{font-size:9px}.upgrade-list{grid-template-columns:1fr}.scene-caption{font-size:8px}.tree-left{left:3%}.tree-right{right:2%}.encounter-wrap{bottom:80px}.wild-tag{bottom:53px}.modal-card{padding:27px 22px}}
@media(max-width:370px){.header-center{display:none}.trail-heading h1{font-size:24px}.scene-art{height:260px}.action-button small{max-width:72px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.upgrade-buy{padding:7px 6px}}

const species=[
 {id:'spriglet',name:'Spriglet',type:'Leaf',color:'#83bd70',light:'#c5df8d',accent:'#f3d87a',shape:'leaf',emoji:'🌱',note:'A curious sprout that follows warm sunlight.'},
 {id:'puddlepop',name:'Puddlepop',type:'Water',color:'#69b8c5',light:'#b4e5e3',accent:'#f4d7a4',shape:'round',emoji:'💧',note:'A bouncy little splash with a big heart.'},
 {id:'emberkit',name:'Emberkit',type:'Ember',color:'#e88961',light:'#ffc28b',accent:'#f7df8b',shape:'cat',emoji:'🔥',note:'Its tiny tail glows brighter when it is happy.'},
 {id:'mossbun',name:'Mossbun',type:'Leaf',color:'#80a96e',light:'#c8d89a',accent:'#e9a1a1',shape:'bunny',emoji:'🍃',note:'Soft moss grows between its long ears.'},
 {id:'cloudlet',name:'Cloudlet',type:'Air',color:'#a9bfce',light:'#e5eff0',accent:'#f7d985',shape:'cloud',emoji:'☁️',note:'It drifts along wherever the breeze takes it.'},
 {id:'pebblit',name:'Pebblit',type:'Stone',color:'#a9957d',light:'#d7c6a5',accent:'#e4a77d',shape:'rock',emoji:'🪨',note:'A sturdy friend who loves a sunny nap.'},
 {id:'glimmeray',name:'Glimmeray',type:'Air',color:'#a28ac8',light:'#ddd2ef',accent:'#f1d581',shape:'wing',emoji:'✨',note:'A shy dusk dancer with a twinkly trail.'},
 {id:'bloomble',name:'Bloomble',type:'Leaf',color:'#df91a1',light:'#f7cfbd',accent:'#f6df87',shape:'flower',emoji:'🌸',note:'It hums little songs to every flower.'},
 {id:'voltkit',name:'Voltkit',type:'Spark',color:'#e2b34e',light:'#f8df91',accent:'#fff1bb',shape:'cat',emoji:'⚡',note:'A playful spark that can never sit still.'},
 {id:'tidefin',name:'Tidefin',type:'Water',color:'#579bb7',light:'#a7d6df',accent:'#f6bd88',shape:'fish',emoji:'🐟',note:'It makes tiny rainbows when it swims.'},
 {id:'nightmew',name:'Nightmew',type:'Dusk',color:'#6f739f',light:'#b8b8d5',accent:'#e8c99a',shape:'cat',emoji:'🌙',note:'A gentle night wanderer with starry whiskers.'},
 {id:'sunpup',name:'Sunpup',type:'Ember',color:'#d58b51',light:'#f3cb84',accent:'#fff0b0',shape:'dog',emoji:'☀️',note:'It brings a little sunshine wherever it goes.'}
];
const zones=[{name:'Whispering Meadow',short:'MEADOW',ids:['spriglet','puddlepop','emberkit','mossbun'],unlock:0,description:'A sunny little trail where new friends grow.'},{name:'Dappled Creek',short:'CREEK',ids:['cloudlet','pebblit','glimmeray','bloomble'],unlock:4,description:'Follow the water and see who comes to play.'},{name:'Sunset Ridge',short:'RIDGE',ids:['voltkit','tidefin','nightmew','sunpup'],unlock:8,description:'A golden path with some rare evening visitors.'}];
const typeColors={Leaf:'#83b878',Water:'#65aec2',Ember:'#e58c64',Air:'#91aebc',Stone:'#ae987d',Spark:'#e4b54e',Dusk:'#8986b2'};
const initial={coins:24,berries:5,xp:0,rank:1,seen:[],team:['spriglet'],zone:0,encounter:0,wild:null,boops:0,goal:0,goalClaimed:false,auto:false,upgrades:{gloves:0,bag:0,radar:0},firstRun:true,day:1};
let state=load();let toastTimer,tipIndex=0,autoTimer=null;
function load(){try{return {...initial,...JSON.parse(localStorage.getItem('pocketwilds-save')||'{}'),upgrades:{...initial.upgrades,...(JSON.parse(localStorage.getItem('pocketwilds-save')||'{}').upgrades||{})}}}catch{return {...initial}}}
function save(){localStorage.setItem('pocketwilds-save',JSON.stringify(state))}
const $=id=>document.getElementById(id);const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
function getSpecies(id){return species.find(x=>x.id===id)}function zoneSpecies(){return zones[state.zone].ids.map(getSpecies)}
function makeWild(){let available=zoneSpecies(),candidate=available[Math.floor(Math.random()*available.length)];if(state.wild&&available.length>1&&candidate.id===state.wild.id)candidate=available[(available.indexOf(candidate)+1)%available.length];let max=12+state.zone*4+state.rank*2;return {id:candidate.id,hp:max,maxHp:max,level:Math.max(1,state.rank+state.zone+Math.floor(Math.random()*2))}}
function svgCreature(s,small=false){let c=s.color,l=s.light,a=s.accent;let ears='';let body='';let decoration='';switch(s.shape){case'leaf':ears=`<path d="M39 54Q19 37 29 18Q49 24 49 48M84 49Q88 23 111 19Q112 43 94 57" fill="${c}" stroke="#344b3b" stroke-width="3" stroke-linejoin="round"/>`;decoration=`<path d="M71 30Q62 17 70 7Q83 19 76 31" fill="${a}" stroke="#344b3b" stroke-width="2.5"/>`;break;case'bunny':ears=`<ellipse cx="49" cy="34" rx="10" ry="29" transform="rotate(-13 49 34)" fill="${c}" stroke="#344b3b" stroke-width="3"/><ellipse cx="89" cy="34" rx="10" ry="29" transform="rotate(12 89 34)" fill="${c}" stroke="#344b3b" stroke-width="3"/><ellipse cx="49" cy="34" rx="4" ry="20" fill="${a}"/><ellipse cx="89" cy="34" rx="4" ry="20" fill="${a}"/>`;break;case'cat':ears=`<path d="M34 59L37 29Q39 23 45 30L58 43M78 42L91 29Q97 24 100 31L102 58" fill="${c}" stroke="#344b3b" stroke-width="3" stroke-linejoin="round"/>`;decoration=`<path d="M96 99Q119 93 111 73" fill="none" stroke="${a}" stroke-width="7" stroke-linecap="round"/>`;break;case'cloud':ears=`<circle cx="43" cy="54" r="18" fill="${l}"/><circle cx="88" cy="48" r="20" fill="${l}"/>`;decoration=`<path d="M40 89Q67 100 95 87" fill="none" stroke="${a}" stroke-width="4" stroke-linecap="round"/>`;break;case'rock':ears=`<path d="M36 58L43 34L59 24L81 28L99 49L96 78L79 94L49 90L34 74Z" fill="${c}" stroke="#344b3b" stroke-width="3" stroke-linejoin="round"/>`;decoration=`<path d="M50 46l9-8m18 4 9 10" stroke="${l}" stroke-width="5" stroke-linecap="round"/>`;break;case'wing':ears=`<path d="M41 62Q14 39 15 62Q20 78 43 80M92 59Q116 35 119 59Q116 77 91 81" fill="${a}" stroke="#344b3b" stroke-width="3"/>`;decoration=`<path d="M66 23l4-9 5 9 9 3-9 4-5 9-4-9-9-4z" fill="${a}" stroke="#344b3b" stroke-width="2"/>`;break;case'flower':ears=`<circle cx="43" cy="43" r="10" fill="${a}"/><circle cx="56" cy="32" r="10" fill="${a}"/><circle cx="70" cy="40" r="10" fill="${a}"/><circle cx="82" cy="31" r="10" fill="${a}"/><circle cx="94" cy="45" r="10" fill="${a}"/>`;break;case'fish':ears=`<path d="M35 65L17 47L17 82Z" fill="${a}" stroke="#344b3b" stroke-width="3"/><path d="M90 48Q106 34 113 51M88 85Q104 96 111 82" fill="none" stroke="${a}" stroke-width="6" stroke-linecap="round"/>`;break;case'dog':ears=`<path d="M39 48Q19 31 22 55L39 75M91 48Q110 29 113 53L96 73" fill="${c}" stroke="#344b3b" stroke-width="3" stroke-linejoin="round"/>`;decoration=`<path d="M91 96Q116 105 109 79" fill="none" stroke="${a}" stroke-width="7" stroke-linecap="round"/>`;break;case'round':ears=`<circle cx="40" cy="52" r="15" fill="${l}"/><circle cx="94" cy="49" r="18" fill="${l}"/><path d="M94 41q9-8 15 2" fill="none" stroke="${a}" stroke-width="4" stroke-linecap="round"/>`;break;}
let mainBody=s.shape==='rock'?`<path d="M35 67Q35 41 66 40Q98 39 101 67L96 91Q90 106 68 107Q43 107 37 91Z" fill="${l}" stroke="#344b3b" stroke-width="3"/>`:`<ellipse cx="68" cy="75" rx="34" ry="32" fill="${l}" stroke="#344b3b" stroke-width="3"/>`;
let face=s.shape==='fish'?`<circle cx="87" cy="66" r="3.5" fill="#344b3b"/><path d="M80 76q8 6 14 0" fill="none" stroke="#344b3b" stroke-width="2" stroke-linecap="round"/><ellipse cx="73" cy="80" rx="14" ry="11" fill="${a}" opacity=".55"/>`:`<ellipse cx="56" cy="72" rx="2.6" ry="3.7" fill="#344b3b"/><ellipse cx="79" cy="72" rx="2.6" ry="3.7" fill="#344b3b"/><path d="M62 82q6 6 12 0" fill="none" stroke="#344b3b" stroke-width="2" stroke-linecap="round"/><ellipse cx="49" cy="80" rx="5" ry="3" fill="${a}" opacity=".65"/><ellipse cx="86" cy="80" rx="5" ry="3" fill="${a}" opacity=".65"/>`;
return `<svg viewBox="0 0 136 120" role="img" aria-label="${s.name}"><ellipse cx="68" cy="106" rx="22" ry="5" fill="#426b4550"/>${ears}${decoration}${mainBody}<ellipse cx="68" cy="91" rx="17" ry="11" fill="${c}" opacity=".75"/>${face}<path d="M43 93q-8 7-11 0m71 0q8 7 11 0" fill="none" stroke="#344b3b" stroke-width="3" stroke-linecap="round"/></svg>`}
function render(){const s=getSpecies(state.wild?.id)||species[0];$('coins').textContent=state.coins;$('berries').textContent=state.berries;$('rank').textContent=state.rank;$('xp').textContent=state.xp;$('xp-next').textContent=state.rank*30;$('day-count').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('wild-name').textContent=s.name;$('health-name').textContent=s.name.toUpperCase();$('wild-level').textContent=state.wild.level;$('encounter-num').textContent=String(state.encounter+1).padStart(2,'0');$('hp-text').textContent=state.wild.hp;$('max-hp').textContent=state.wild.maxHp;$('health-fill').style.width=`${Math.max(4,state.wild.hp/state.wild.maxHp*100)}%`;$('health-fill').classList.toggle('low',state.wild.hp/state.wild.maxHp<.4);$('wild-type-dot').style.background=typeColors[s.type];$('wild-creature').innerHTML=svgCreature(s);$('team-count').textContent=`${state.team.length} / 4`;$('guide-count').textContent=`${state.seen.length} / 12`;$('zone-caught').textContent=zones[state.zone].ids.filter(id=>state.seen.includes(id)).length;$('zone-progress').style.width=`${zones[state.zone].ids.filter(id=>state.seen.includes(id)).length/4*100}%`;$('auto-btn').classList.toggle('on',state.auto);$('auto-state').textContent=state.auto?'ON':'OFF';$('catch-cost').textContent=state.berries===1?'1 wild berry':'1 wild berry';$('goal-progress-text').textContent=`${Math.min(state.goal,3)} / 3`;$('goal-fill').style.width=`${Math.min(state.goal,3)/3*100}%`;$('goal-title').textContent=state.goalClaimed?'Little goal complete!':'Say hello to 3 wilds';$('goal-fill').style.background=state.goalClaimed?'#e4b456':'#84bd77';$('zone-button').querySelectorAll('span')[1].textContent=zones[state.zone].short;
$('team-list').innerHTML=state.team.length?state.team.map(id=>{let p=getSpecies(id);return `<div class="team-member"><div class="team-sprite" style="background:${p.light}">${p.emoji}</div><div class="team-copy"><div class="team-name">${p.name}</div><div class="team-lv">LV. ${Math.max(1,state.rank)}</div></div><span class="team-heart">♥</span></div>`}).join(''):'<div class="empty-team">Your team is waiting for its first friend.</div>';
$('battle-feedback').textContent=state.wild.hp<=2?'So friendly now! A berry could bring them home.':state.wild.hp<state.wild.maxHp/2?'They are warming up to you. Keep going!':'A new friend is waiting to say hello.';
$('attack-btn').setAttribute('aria-label','Boop the wild');$('activity-list').innerHTML=logItems.length?logItems.slice(0,5).map(x=>`<div class="activity-item"><div class="activity-avatar" style="background:${x.bg}">${x.icon}</div><div class="activity-text">${x.text}<span class="activity-time">${x.time}</span></div></div>`).join(''):'<div class="empty-log">The trail is quiet for now. Go say hello to someone!</div>';
renderGuide();renderCamp();save()}
const logItems=[];function addLog(icon,bg,text){logItems.unshift({icon,bg,text,time:'JUST NOW'});logItems.length=Math.min(8,logItems.length)}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function encounter(){state.encounter++;state.wild=makeWild();addLog('🌿','#edf4e5',`Spotted a wild <b>${getSpecies(state.wild.id).name}</b> on the trail.`);render()}
function gainXp(amount){state.xp+=amount;while(state.xp>=state.rank*30){state.xp-=state.rank*30;state.rank++;state.coins+=8;addLog('⬆','#f3eedc',`You reached <b>Rank ${state.rank}</b>! +8 trail tokens.`);toast(`Rank up! You're now rank ${state.rank} ✨`)}}
function boop(){const upgrade=state.upgrades.gloves;let damage=1+upgrade;state.wild.hp=Math.max(1,state.wild.hp-damage);state.coins+=1+Math.floor(state.upgrades.radar/2);state.boops++;gainXp(2);if(!state.goalClaimed){state.goal=Math.min(3,state.goal+1);if(state.goal>=3){state.goalClaimed=true;state.coins+=12;addLog('✦','#fff4d8','Little goal complete! <b>+12 tokens</b>.');toast('Daily goal complete! +12 trail tokens ✦')}}addLog('↗','#eaf3e4',`You gave <b>${getSpecies(state.wild.id).name}</b> a friendly boop.`);render()}
function tryCatch(){if(state.berries<1){toast('No wild berries left — check your camp upgrades!');return}state.berries--;let trust=1-state.wild.hp/state.wild.maxHp;let chance=clamp(.24+trust*.72+state.upgrades.radar*.04,.24,.96);if(Math.random()<chance){let s=getSpecies(state.wild.id);let fresh=!state.seen.includes(s.id);if(fresh){state.seen.push(s.id);gainXp(8);addLog(s.emoji,'#eff3e5',`Made a new friend: <b>${s.name}</b>!`)}else{state.coins+=4;addLog(s.emoji,'#eff3e5',`Had another lovely hello with <b>${s.name}</b>. +4 tokens.`)}if(state.team.length<4&&!state.team.includes(s.id))state.team.push(s.id);else if(!state.team.includes(s.id))toast(`${s.name} joined your field guide! Team is full.`);state.coins+=3;state.berries+=Math.floor(state.upgrades.bag/2);let zoneCaught=zones[state.zone].ids.filter(id=>state.seen.includes(id)).length;if(fresh&&zoneCaught>=4&&state.zone<2)toast(`Meadow complete! A new trail is waiting in the zone selector.`);else if(fresh)toast(`${s.name} is your new friend! +3 tokens`);state.wild=makeWild();state.encounter++;}else{addLog('●','#fff2e4',`${getSpecies(state.wild.id).name} isn't ready yet. Try a few more boops!`);toast('Not quite yet — try a few more boops!')}render()}
const upgrades=[{id:'gloves',name:'Soft-touch mitts',icon:'🧤',desc:'Make each boop a little stronger.',base:15,max:5},{id:'bag',name:'Berry satchel',icon:'🧺',desc:'Find an extra berry every other new friend.',base:20,max:4},{id:'radar',name:'Wildflower charm',icon:'🧭',desc:'Find rare friends and boost invitations.',base:25,max:4}];
function renderCamp(){$('upgrade-list').innerHTML=upgrades.map(u=>{let level=state.upgrades[u.id],cost=u.base*(level+1),done=level>=u.max;return `<div class="upgrade-card"><div class="upgrade-icon">${u.icon}</div><div class="upgrade-info"><b>${u.name}</b><small>${u.desc}</small><div class="upgrade-level">LEVEL ${level} / ${u.max}</div></div><button class="upgrade-buy" data-upgrade="${u.id}" ${done||state.coins<cost?'disabled':''}>${done?'MAXED':`✦ ${cost}`}</button></div>`}).join('');document.querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>buyUpgrade(btn.dataset.upgrade))}
function buyUpgrade(id){let u=upgrades.find(x=>x.id===id),cost=u.base*(state.upgrades[id]+1);if(state.coins<cost||state.upgrades[id]>=u.max)return;state.coins-=cost;state.upgrades[id]++;addLog(u.icon,'#f3eedc',`Upgraded <b>${u.name}</b> to level ${state.upgrades[id]}.`);toast(`${u.name} upgraded!`);render()}
function renderGuide(){let cards=species.map(s=>{let found=state.seen.includes(s.id);return `<article class="guide-card ${found?'':'undiscovered'}"><div class="guide-art" style="background:linear-gradient(180deg,${found?s.light:'#e9eee7'},#f2f4e9)">${found?`<div class="creature-mini">${svgCreature(s,true)}</div>`:'<div class="unknown-art">?</div>'}</div><div class="guide-card-copy"><b>${found?s.name:'???'}</b><span>${found?`${s.type.toUpperCase()} TYPE · ${s.note}`:'A friend still to be found'}</span></div></article>`}).join('');$('guide-grid').innerHTML=cards;$('guide-total').textContent=state.seen.length}
function setView(view){document.querySelectorAll('.trail-view,.guide-view,.camp-view').forEach(x=>x.classList.add('hidden'));$(`${view}-view`).classList.remove('hidden');document.querySelectorAll('.nav-item,.mobile-nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='camp')renderCamp()}
function setAuto(on){state.auto=on;clearInterval(autoTimer);if(on)autoTimer=setInterval(()=>{if(state.auto&&$('trail-view').classList.contains('hidden')===false)boop()},1250);render()}
const tips=['Booping a wild makes it easier to befriend. A gentle hello goes a long way!','Wild berries work best when a friend is feeling safe and happy.','A bigger team earns you bragging rights. Collect all 12 friends in your guide!','Soft-touch mitts make every boop count double. Look for upgrades at base camp.','Complete the meadow collection to unlock the next trail. Keep exploring!'];
function init(){if(!state.wild)state.wild=makeWild();document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.view)));$('attack-btn').onclick=boop;$('catch-btn').onclick=tryCatch;$('auto-btn').onclick=()=>setAuto(!state.auto);$('sound-btn').onclick=()=>toast('Sound effects are coming soon!');$('help-btn').onclick=()=>$('modal').classList.remove('hidden');$('modal-close').onclick=()=>$('modal').classList.add('hidden');$('got-it').onclick=()=>$('modal').classList.add('hidden');$('reset-game').onclick=()=>{localStorage.removeItem('pocketwilds-save');location.reload()};$('tip-next').onclick=()=>{$('tip-text').textContent=tips[tipIndex++%tips.length]};$('zone-button').onclick=()=>{if(state.zone<2&&zones[state.zone].ids.every(id=>state.seen.includes(id))){let next=state.zone+1,cost=35*next;if(state.coins<cost){toast(`Need ${cost} trail tokens to explore ${zones[next].short.toLowerCase()}.`);return}state.coins-=cost;state.zone=next;state.wild=makeWild();state.encounter++;toast(`Welcome to ${zones[next].name}!`);render()}else{toast(state.zone===2?'You found the last trail!':'Meet all 4 meadow locals to unlock the next trail.')}};document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!e.target.matches('button')){e.preventDefault();boop()}});render();if(state.firstRun){$('modal').classList.remove('hidden');state.firstRun=false;save()}}
init();

