17:const initial={coins:24,berries:5,xp:0,rank:1,seen:[],team:['spriglet'],zone:0,encounter:0,wild:null,boops:0,goal:0,goalClaimed:false,auto:false,upgrades:{gloves:0,bag:0,radar:0},firstRun:true,day:1};
37:function boop(){const upgrade=state.upgrades.gloves;let damage=1+upgrade;state.wild.hp=Math.max(1,state.wild.hp-damage);state.coins+=1+Math.floor(state.upgrades.radar/2);state.boops++;gainXp(2);if(!state.goalClaimed){state.goal=Math.min(3,state.goal+1);if(state.goal>=3){state.goalClaimed=true;state.coins+=12;addLog('✦','#fff4d8','Little goal complete! <b>+12 tokens</b>.');toast('Daily goal complete! +12 trail tokens ✦')}}addLog('↗','#eaf3e4',`You gave <b>${getSpecies(state.wild.id).name}</b> a friendly boop.`);render()}
38:function tryCatch(){if(state.berries<1){toast('No wild berries left — check your camp upgrades!');return}state.berries--;let trust=1-state.wild.hp/state.wild.maxHp;let chance=clamp(.24+trust*.72+state.upgrades.radar*.04,.24,.96);if(Math.random()<chance){let s=getSpecies(state.wild.id);let fresh=!state.seen.includes(s.id);if(fresh){state.seen.push(s.id);gainXp(8);addLog(s.emoji,'#eff3e5',`Made a new friend: <b>${s.name}</b>!`)}else{state.coins+=4;addLog(s.emoji,'#eff3e5',`Had another lovely hello with <b>${s.name}</b>. +4 tokens.`)}if(state.team.length<4&&!state.team.includes(s.id))state.team.push(s.id);else if(!state.team.includes(s.id))toast(`${s.name} joined your field guide! Team is full.`);state.coins+=3;state.berries+=Math.floor(state.upgrades.bag/2);let zoneCaught=zones[state.zone].ids.filter(id=>state.seen.includes(id)).length;if(fresh&&zoneCaught>=4&&state.zone<2)toast(`Meadow complete! A new trail is waiting in the zone selector.`);else if(fresh)toast(`${s.name} is your new friend! +3 tokens`);state.wild=makeWild();state.encounter++;}else{addLog('●','#fff2e4',`${getSpecies(state.wild.id).name} isn't ready yet. Try a few more boops!`);toast('Not quite yet — try a few more boops!')}render()}
39:const upgrades=[{id:'gloves',name:'Soft-touch mitts',icon:'🧤',desc:'Make each boop a little stronger.',base:15,max:5},{id:'bag',name:'Berry satchel',icon:'🧺',desc:'Find an extra berry every other new friend.',base:20,max:4},{id:'radar',name:'Wildflower charm',icon:'🧭',desc:'Find rare friends and boost invitations.',base:25,max:4}];
43:function setView(view){document.querySelectorAll('.trail-view,.guide-view,.camp-view').forEach(x=>x.classList.add('hidden'));$(`${view}-view`).classList.remove('hidden');document.querySelectorAll('.nav-item,.mobile-nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='camp')renderCamp()}
44:function setAuto(on){state.auto=on;clearInterval(autoTimer);if(on)autoTimer=setInterval(()=>{if(state.auto&&$('trail-view').classList.contains('hidden')===false)boop()},1250);render()}
45:const tips=['Booping a wild makes it easier to befriend. A gentle hello goes a long way!','Wild berries work best when a friend is feeling safe and happy.','A bigger team earns you bragging rights. Collect all 12 friends in your guide!','Soft-touch mitts make every boop count double. Look for upgrades at base camp.','Complete the meadow collection to unlock the next trail. Keep exploring!'];
46:function init(){if(!state.wild)state.wild=makeWild();document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.view)));$('attack-btn').onclick=boop;$('catch-btn').onclick=tryCatch;$('auto-btn').onclick=()=>setAuto(!state.auto);$('sound-btn').onclick=()=>toast('Sound effects are coming soon!');$('help-btn').onclick=()=>$('modal').classList.remove('hidden');$('modal-close').onclick=()=>$('modal').classList.add('hidden');$('got-it').onclick=()=>$('modal').classList.add('hidden');$('reset-game').onclick=()=>{localStorage.removeItem('pocketwilds-save');location.reload()};$('tip-next').onclick=()=>{$('tip-text').textContent=tips[tipIndex++%tips.length]};$('zone-button').onclick=()=>{if(state.zone<2&&zones[state.zone].ids.every(id=>state.seen.includes(id))){let next=state.zone+1,cost=35*next;if(state.coins<cost){toast(`Need ${cost} trail tokens to explore ${zones[next].short.toLowerCase()}.`);return}state.coins-=cost;state.zone=next;state.wild=makeWild();state.encounter++;toast(`Welcome to ${zones[next].name}!`);render()}else{toast(state.zone===2?'You found the last trail!':'Meet all 4 meadow locals to unlock the next trail.')}};document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!e.target.matches('button')){e.preventDefault();boop()}});render();if(state.firstRun){$('modal').classList.remove('hidden');state.firstRun=false;save()}}
